// Port of Reportman.Drawing.Translator: the engine messages by index, from the reportmanres
// tables (Reportman.Drawing/Resources/reportmanres.en and .es, generated by
// test/generate-translations.mjs).

import type { CultureInfo } from './culture.js';
import { REPORTMANRES_EN } from './reportmanres.en.generated.js';
import { REPORTMANRES_ES } from './reportmanres.es.generated.js';

const DEFAULT_STRING = 'XXXXXXX';

/** The message languages with built-in tables. */
export type MessageLanguage = 'en' | 'es';

/**
 * Translator.LoadFromStream: UTF-16LE text, one string per LF; a doubled LF is a literal LF inside
 * the current string. The index of a string is its position.
 */
export function parseTranslationBytes(bytes: Uint8Array): string[] {
  const content: string[] = [];
  let current = '';
  let foundlf = false;
  const pairs = Math.floor(bytes.length / 2);
  for (let i = 0; i < pairs; i++) {
    const code = (bytes[i * 2 + 1]! << 8) + bytes[i * 2]!;
    if (code === 10) {
      if (foundlf) {
        foundlf = false;
        current += '\n';
      } else foundlf = true;
    } else {
      if (foundlf) {
        content.push(current);
        current = '';
        foundlf = false;
      }
      current += String.fromCharCode(code);
    }
  }
  if (current.length > 0) content.push(current);
  return content;
}

/**
 * Translator.TranslateStr. The C# engine loads the table of the thread culture (the Spanish one for
 * a Spanish culture, English otherwise: its resources are only .en and .es); here the table is
 * chosen explicitly.
 */
export class Translator {
  /** The active translation (atrans in C#). */
  readonly strings: readonly string[];
  /** DefaultStrings in C#: used when the active translation has fewer strings. */
  readonly defaults: readonly string[];

  constructor(strings: readonly string[], defaults: readonly string[] = strings) {
    this.strings = strings;
    this.defaults = defaults;
  }

  static readonly english = new Translator(REPORTMANRES_EN);
  static readonly spanish = new Translator(REPORTMANRES_ES);

  static forLanguage(language: MessageLanguage): Translator {
    return language === 'es' ? Translator.spanish : Translator.english;
  }

  /** The translator the C# engine uses under a culture: Spanish for "es", English otherwise. */
  static forCulture(culture: CultureInfo): Translator {
    return culture.twoLetterISOLanguageName.toUpperCase() === 'ES' ? Translator.spanish : Translator.english;
  }

  /** A translator from a reportmanres file (UTF-16LE), with a built-in table as defaults. */
  static fromBytes(bytes: Uint8Array, defaults: MessageLanguage = 'en'): Translator {
    return new Translator(parseTranslationBytes(bytes), Translator.forLanguage(defaults).strings);
  }

  translateStr(index: number): string {
    let value: string;
    if (this.strings.length > index && index >= 0) value = this.strings[index]!;
    else if (index >= 0 && index < this.defaults.length) value = this.defaults[index]!;
    else value = DEFAULT_STRING;
    if (index === 448) value = value.split('%s').join('{0}');
    return value;
  }
}
